// guardrails-packs.mjs: the pack registry. Generated by agentic-guardrail-ts.
// The engine (guardrails.mjs) is language-agnostic; everything stack-specific is declared here.
// See docs/packs.md for the contract. Adding a stack means adding a pack object below.
//
// A pack:    { id, detect: [RegExp on repo paths], tools: [tool] }
// A tool:
//   id        finding prefix; keys are `id:rule|file`
//   optIn     [config file | { file, has: RegExp }]: the tool is on when any of them matches
//   exts      files the tool covers (RegExp), so the hooks can scope it; omit for all tracked files
//   track     extra file types to start tracking when the tool is on (does not filter)
//   stages    where it runs: 'edit' (post-edit hook), 'commit' (pre-commit, --files, --changed and
//             the stop hook), 'push' (full check: pre-push and CI)
//   whole     true: always runs on the whole project; findings are then filtered to the scope
//   perFile   true: one command per file
//   ok        exit codes that mean "ran" (default [0, 1]); anything else is a tool failure
//   run(ctx)  returns { cmd, args } (null skips); ctx = { files, online, tmp(name), h }
//   parse(out, ctx)  out = { stdout, stderr, status }; returns [{ rule, file, line, message }]
//   scan(ctx) replaces run+parse for checks done in JS
//   metric + measure(ctx)  a number ratchet instead of findings: { name, direction, unit, advice }

import { mkdirSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { join } from 'node:path';

const TS_EXT = /\.[cm]?[jt]sx?$/;
const MD_EXT = /\.mdx?$/;
const PY_EXT = /\.py$/;

// Exit codes for tools whose JSON report is the authority (v3 ignored their exit status): any exit
// is fine as long as the report parses, and an unparsable report throws.
const ANY_EXIT = Array.from({ length: 256 }, (_, i) => i);

// ── Parsing helpers ──

const tail = (s) => s.trim().slice(-2000);

// Colour codes some tools print even when piped.
const ANSI = new RegExp(`${String.fromCharCode(27)}\\[[0-9;]*m`, 'g');

// One finding per output line that matches `re`; `make(match)` returns { rule, file, line, message }.
const lines =
  (re, make, from = 'stdout') =>
  (out) =>
    out[from].split('\n').flatMap((l) => {
      const m = re.exec(l.replaceAll(ANSI, ''));
      return m ? [make(m)] : [];
    });

const json = (tool, text) => {
  try {
    return JSON.parse(text);
  } catch {
    throw new Error(`${tool} printed no JSON:\n${tail(text)}`);
  }
};

// Files for a command, or the whole-project fallback when the run is not scoped.
const targets = (ctx, fallback) => ctx.files ?? fallback;

// ── ts: the TypeScript stack. Each tool is on when its config file exists, which every v3 install has ──

// Every list-valued field of a Knip issue is a finding: unused files, exports, dependencies.
const knipItems = (issue) =>
  Object.entries(issue)
    .filter(([, items]) => Array.isArray(items))
    .flatMap(([type, items]) =>
      items.map((item) => ({
        rule: type,
        file: issue.file,
        line: item.line,
        message: item.name ?? type,
      })),
    );

// v3 ran Oxlint unconditionally and Knip whenever its binary was installed. So each tool is on
// when it has any supported config file, or when the package is a dependency (the v3 shape).
const OXLINT_ON = [
  '.oxlintrc.json',
  '.oxlintrc.jsonc',
  'oxlint.config.ts',
  { file: 'package.json', has: /"oxlint"\s*:/ },
];
const KNIP_ON = [
  'knip.json',
  'knip.jsonc',
  '.knip.json',
  '.knip.jsonc',
  'knip.ts',
  'knip.js',
  'knip.config.ts',
  'knip.config.js',
  'knip.config.mjs',
  { file: 'package.json', has: /"knip"\s*:/ },
];

const ts = {
  id: 'ts',
  detect: [/(^|\/)package\.json$/, /(^|\/)tsconfig[^/]*\.json$/],
  tools: [
    {
      id: 'oxlint',
      optIn: OXLINT_ON,
      ok: ANY_EXIT,
      exts: TS_EXT,
      stages: ['edit', 'commit', 'push'],
      run: ({ files, h }) =>
        files?.length === 0
          ? null
          : {
              cmd: h.needBin('oxlint'),
              args: [
                '--type-aware',
                '--report-unused-disable-directives',
                '-f',
                'json',
                ...(files ?? []),
              ],
            },
      parse: (out) =>
        json('oxlint', out.stdout).diagnostics.map((d) => ({
          rule: d.code ?? 'unused-disable-directive',
          file: d.filename,
          line: d.labels?.[0]?.span?.line,
          message: d.message,
        })),
    },
    {
      id: 'depcruise',
      optIn: ['.dependency-cruiser.mjs', '.dependency-cruiser.cjs', '.dependency-cruiser.js'],
      // dependency-cruiser exits with the number of errors, so any code is a normal report.
      ok: ANY_EXIT,
      exts: TS_EXT,
      stages: ['commit', 'push'],
      run: ({ files, h }) => {
        const config = [
          '.dependency-cruiser.mjs',
          '.dependency-cruiser.cjs',
          '.dependency-cruiser.js',
        ].find((f) => h.exists(f));
        const dirs = files ?? h.sourceDirs();
        if (!config || dirs.length === 0) return null;
        return {
          cmd: h.needBin('depcruise'),
          args: [...dirs, '-c', config, '-T', 'json', '--no-ignore-known'],
        };
      },
      parse: (out) =>
        json('depcruise', out.stdout).summary.violations.map((v) => ({
          rule: v.rule.name,
          file: v.from,
          message: v.to === v.from ? v.rule.name : `imports ${v.to}`,
        })),
    },
    {
      // Needs the whole graph, so full checks only.
      id: 'knip',
      optIn: KNIP_ON,
      ok: ANY_EXIT,
      stages: ['push'],
      whole: true,
      run: ({ h }) => {
        // Knip only runs when a switch turned it on (a config file, a knip.config.*, or a knip
        // entry in package.json), and then a missing binary is a broken install, never a skip.
        return { cmd: h.needBin('knip'), args: ['--reporter', 'json', '--no-progress'] };
      },
      parse: (out) => json('knip', out.stdout).issues.flatMap(knipItems),
    },
    {
      // Every disable comment needs a rule and a reason.
      id: 'guardrails',
      optIn: OXLINT_ON,
      exts: TS_EXT,
      stages: ['edit', 'commit', 'push'],
      scan: ({ files, h }) => {
        const pattern = /\/[/*]\s*(?:eslint|oxlint)-disable(?:-next-line|-line)?\b([^\n]*)/g;
        const found = [];
        for (const file of files ?? h.projectFiles()) {
          h.read(file)
            .split('\n')
            .forEach((text, i) => {
              for (const m of text.matchAll(pattern)) {
                const [rules, reason] = m[1].replace(/\*\/.*$/, '').split(/\s(?:--|—)\s/);
                if (rules?.trim() && reason?.trim()) continue;
                found.push({
                  rule: 'disable-needs-rule-and-reason',
                  file,
                  line: i + 1,
                  message: 'name the rule and add "-- <reason>"',
                });
              }
            });
        }
        return found;
      },
    },
  ],
};

// ── vocab-literal: raw strings that equal a member of the project's vocab module ──

const VOCAB_CONFIG = 'guardrails/vocab.json';
const VOCAB_EXT = /\.(?:[cm]?[jt]sx?|py)$/;
const TEST_FILE =
  /(?:^|\/)(?:__tests__|tests?|e2e)\/|\.(?:test|spec)\.[^/]+$|(?:^|\/)test_[^/]*\.py$|_test\.py$|(?:^|\/)conftest\.py$/;

// A glob from vocab.json `ignore`: `**` crosses folders, `*` and `?` stay inside one.
const globRegExp = (glob) =>
  new RegExp(
    `^${glob
      .replace(/[.+^${}()|[\]\\]/g, '\\$&')
      .replaceAll('**/', '\u0000')
      .replaceAll('**', '\u0001')
      .replaceAll('*', '[^/]*')
      .replaceAll('?', '[^/]')
      .replaceAll('\u0000', '(?:.*/)?')
      .replaceAll('\u0001', '.*')}$`,
  );

// The project's own TypeScript package parses TS and JS files. Missing means a broken install.
function loadTypescript(h) {
  try {
    return createRequire(join(h.ROOT, 'package.json'))('typescript');
  } catch (e) {
    throw new Error(
      `${VOCAB_CONFIG}: the typescript package is needed to read TypeScript vocab and sources. Install devDependencies first.`,
      { cause: e },
    );
  }
}

// `as const` and `satisfies` wrappers around the expression.
const unwrap = (tsApi, node) =>
  tsApi.isAsExpression(node) ||
  tsApi.isSatisfiesExpression(node) ||
  tsApi.isParenthesizedExpression(node)
    ? unwrap(tsApi, node.expression)
    : node;

const isConstAssertion = (tsApi, node) =>
  (tsApi.isAsExpression(node) &&
    tsApi.isTypeReferenceNode(node.type) &&
    node.type.typeName.text === 'const') ||
  ((tsApi.isSatisfiesExpression(node) || tsApi.isParenthesizedExpression(node)) &&
    isConstAssertion(tsApi, node.expression));

const isStringNode = (tsApi, node) =>
  tsApi.isStringLiteral(node) || tsApi.isNoSubstitutionTemplateLiteral(node);

const propertyName = (tsApi, name) =>
  tsApi.isIdentifier(name) || tsApi.isStringLiteral(name) || tsApi.isNumericLiteral(name)
    ? name.text
    : null;

// Members of an object literal, nested objects included (`Outer.Inner.KEY`).
function tsObjectMembers(tsApi, object, prefix) {
  const found = [];
  for (const p of object.properties) {
    const key = tsApi.isPropertyAssignment(p) ? propertyName(tsApi, p.name) : null;
    if (key === null) continue;
    const value = unwrap(tsApi, p.initializer);
    if (isStringNode(tsApi, value)) found.push([`${prefix}.${key}`, value.text]);
    else if (tsApi.isObjectLiteralExpression(value)) {
      found.push(...tsObjectMembers(tsApi, value, `${prefix}.${key}`));
    }
  }
  return found;
}

const tsKind = (tsApi, file) => {
  if (file.endsWith('.tsx')) return tsApi.ScriptKind.TSX;
  if (/\.[cm]?ts$/.test(file)) return tsApi.ScriptKind.TS;
  return file.endsWith('.jsx') ? tsApi.ScriptKind.JSX : tsApi.ScriptKind.JS;
};

const tsParse = (tsApi, file, text) =>
  tsApi.createSourceFile(file, text, tsApi.ScriptTarget.Latest, true, tsKind(tsApi, file));

// The names a module exports without a modifier: `export { A, B as C }` and `export default A`.
function tsExportedNames(tsApi, sf) {
  const names = new Map();
  for (const st of sf.statements) {
    if (tsApi.isExportDeclaration(st) && !st.moduleSpecifier && st.exportClause) {
      for (const el of tsApi.isNamedExports(st.exportClause) ? st.exportClause.elements : []) {
        names.set((el.propertyName ?? el.name).text, el.name.text);
      }
    } else if (tsApi.isExportAssignment(st) && tsApi.isIdentifier(st.expression)) {
      names.set(st.expression.text, st.expression.text);
    }
  }
  return names;
}

const hasExportModifier = (tsApi, node) =>
  (tsApi.canHaveModifiers(node) ? (tsApi.getModifiers(node) ?? []) : []).some(
    (m) => m.kind === tsApi.SyntaxKind.ExportKeyword,
  );

// TypeScript: `export const X = { A: 'a' } as const` and `enum X { A = 'a' }`, at module scope or
// inside an exported namespace, named the way a caller writes them (`Domain.Status.Active`).
// Declarations inside functions or blocks, and names that are not exported, are not members.
function tsVocab(tsApi, file, text) {
  const sf = tsParse(tsApi, file, text);
  const renamed = tsExportedNames(tsApi, sf);
  const found = [];
  // The name a caller writes for a declaration, or null when it is not reachable. `top` is true at
  // module scope, false in a namespace (members need `export`), 'inner' for `namespace A.B`.
  const exportedAs = (node, name, top) => {
    if (top === 'inner' || hasExportModifier(tsApi, node)) return name;
    return top === true ? (renamed.get(name) ?? null) : null;
  };
  const collectModule = (mod, prefix, top) => {
    const name = tsApi.isIdentifier(mod.name) ? exportedAs(mod, mod.name.text, top) : null;
    if (name === null || !mod.body) return;
    if (tsApi.isModuleBlock(mod.body)) collect(mod.body.statements, `${prefix}${name}.`, false);
    else if (tsApi.isModuleDeclaration(mod.body))
      collectModule(mod.body, `${prefix}${name}.`, 'inner');
  };
  const collectStatement = (st, prefix, top) => {
    if (tsApi.isEnumDeclaration(st)) {
      const name = exportedAs(st, st.name.text, top);
      if (name !== null) found.push(...tsEnumMembers(tsApi, st, `${prefix}${name}`));
    } else if (tsApi.isVariableStatement(st)) {
      for (const d of st.declarationList.declarations) {
        const name = tsApi.isIdentifier(d.name) ? exportedAs(st, d.name.text, top) : null;
        if (name !== null) found.push(...tsConstObjectMembers(tsApi, d, `${prefix}${name}`));
      }
    } else if (tsApi.isModuleDeclaration(st)) {
      collectModule(st, prefix, top);
    }
  };
  const collect = (statements, prefix, top) => {
    for (const st of statements) collectStatement(st, prefix, top);
  };
  collect(sf.statements, '', true);
  return found;
}

// `Name.Key` and value of each string member of an enum.
function tsEnumMembers(tsApi, node, name) {
  const found = [];
  for (const m of node.members) {
    const key = propertyName(tsApi, m.name);
    const value = m.initializer && unwrap(tsApi, m.initializer);
    if (key !== null && value && isStringNode(tsApi, value))
      found.push([`${name}.${key}`, value.text]);
  }
  return found;
}

// Members of `const X = { ... } as const`; nothing for any other declaration.
function tsConstObjectMembers(tsApi, decl, name) {
  if (!decl.initializer || !isConstAssertion(tsApi, decl.initializer)) return [];
  const value = unwrap(tsApi, decl.initializer);
  return tsApi.isObjectLiteralExpression(value) ? tsObjectMembers(tsApi, value, name) : [];
}

// A string that names a module (imports, re-exports, require(), import(), `declare module`).
function isModuleName(tsApi, node) {
  const p = node.parent;
  return (
    tsApi.isImportDeclaration(p) ||
    tsApi.isExportDeclaration(p) ||
    tsApi.isExternalModuleReference(p) ||
    tsApi.isModuleDeclaration(p) ||
    (tsApi.isLiteralTypeNode(p) && tsApi.isImportTypeNode(p.parent)) ||
    (tsApi.isCallExpression(p) &&
      (p.expression.kind === tsApi.SyntaxKind.ImportKeyword ||
        (tsApi.isIdentifier(p.expression) && p.expression.text === 'require')))
  );
}

// Plain string literals of a TS or JS file. A template contributes only the literals inside its
// substitutions (its own text is not a plain string unless it has none).
function tsLiterals(tsApi, file, text) {
  const sf = tsParse(tsApi, file, text);
  const found = [];
  const visit = (node) => {
    if (isStringNode(tsApi, node) && !isModuleName(tsApi, node)) {
      found.push({
        value: node.text,
        line: sf.getLineAndCharacterOfPosition(node.getStart(sf)).line + 1,
      });
    }
    tsApi.forEachChild(node, visit);
  };
  visit(sf);
  return found;
}

// Python is read by its own `ast` module. A member is an assignment directly in the body of a
// StrEnum (or str + Enum) class; a literal is any str constant except a bare-string statement
// (a docstring) and the fixed text of an f-string, whose substitutions are walked.
const PY_READER = `
import ast, json, sys
req = json.load(sys.stdin)

def enum_aliases(tree):
    names = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom) and node.module == "enum":
            for alias in node.names:
                names[alias.asname or alias.name] = alias.name
    return names

def is_str(node):
    return isinstance(node, ast.Constant) and isinstance(node.value, str)

def exported_names(tree):
    for stmt in tree.body:
        if isinstance(stmt, ast.Assign) and any(isinstance(t, ast.Name) and t.id == "__all__" for t in stmt.targets):
            if isinstance(stmt.value, (ast.List, ast.Tuple)) and all(is_str(e) for e in stmt.value.elts):
                return {e.value for e in stmt.value.elts}
    return None

def members(tree):
    aliases = enum_aliases(tree)
    public = exported_names(tree)
    out = []

    def is_enum(cls):
        names = set()
        for b in cls.bases:
            if isinstance(b, ast.Name):
                names.add(aliases.get(b.id, b.id))
            elif isinstance(b, ast.Attribute):
                names.add(b.attr)
        return "StrEnum" in names or ("str" in names and "Enum" in names)

    def walk(body, prefix, top):
        for cls in body:
            if not isinstance(cls, ast.ClassDef) or cls.name.startswith("_"):
                continue
            if top and public is not None and cls.name not in public:
                continue
            name = prefix + cls.name
            if is_enum(cls):
                for stmt in cls.body:
                    if isinstance(stmt, ast.Assign) and len(stmt.targets) == 1:
                        target, value = stmt.targets[0], stmt.value
                    elif isinstance(stmt, ast.AnnAssign) and stmt.value is not None:
                        target, value = stmt.target, stmt.value
                    else:
                        continue
                    if isinstance(target, ast.Name) and is_str(value):
                        out.append([name + "." + target.id, value.value])
            walk(cls.body, name + ".", False)

    walk(tree.body, "", True)
    return out

class Literals(ast.NodeVisitor):
    def __init__(self):
        self.out = []

    def visit_Expr(self, node):
        if not is_str(node.value):
            self.generic_visit(node)

    def visit_Constant(self, node):
        if isinstance(node.value, str):
            self.out.append([node.value, node.lineno])

    def visit_JoinedStr(self, node):
        fields = [v for v in node.values if isinstance(v, ast.FormattedValue)]
        if not fields:
            self.out.append(["".join(v.value for v in node.values), node.lineno])
        for field in fields:
            self.visit(field.value)
            spec = field.format_spec
            for inner in (spec.values if spec else []):
                if isinstance(inner, ast.FormattedValue):
                    self.visit(inner.value)

result = {"vocab": {}, "scan": {}}
for path in req["vocab"]:
    result["vocab"][path] = members(ast.parse(open(path, encoding="utf-8").read(), path))
for path in req["scan"]:
    visitor = Literals()
    visitor.visit(ast.parse(open(path, encoding="utf-8").read(), path))
    result["scan"][path] = visitor.out
json.dump(result, sys.stdout)
`;

function readPython(h, vocab, scan) {
  if (vocab.length === 0) return { vocab: {}, scan: {} };
  const r = h.run('python3', ['-I', '-c', PY_READER], {
    input: JSON.stringify({ vocab, scan }),
  });
  if (r.status !== 0) {
    throw new Error(
      `${VOCAB_CONFIG}: python3 could not read the Python files (exit ${r.status}):\n${tail(r.stderr || String(r.error ?? ''))}`,
    );
  }
  return json('python3', r.stdout);
}

function vocabConfig(h) {
  let config;
  try {
    config = JSON.parse(h.read(VOCAB_CONFIG));
  } catch (e) {
    throw new Error(`${VOCAB_CONFIG} is not valid JSON: ${e.message}`, { cause: e });
  }
  const modules = config.modules;
  if (
    !Array.isArray(modules) ||
    modules.length === 0 ||
    !modules.every((m) => typeof m === 'string')
  ) {
    throw new Error(`${VOCAB_CONFIG} needs "modules": ["path/to/vocab.ts", ...]`);
  }
  for (const mod of modules) {
    if (!h.exists(mod)) throw new Error(`${VOCAB_CONFIG}: vocab module ${mod} does not exist`);
  }
  return { modules, ignore: (config.ignore ?? []).map(globRegExp) };
}

// value -> member name, per language, from every vocab module.
function vocabTables(h, modules, tsApi, pyVocab) {
  const tables = { ts: new Map(), py: new Map() };
  for (const mod of modules) {
    const py = PY_EXT.test(mod);
    const parsed = py ? pyVocab[mod] : tsVocab(tsApi, mod, h.read(mod));
    if (parsed.length === 0) {
      throw new Error(
        `${VOCAB_CONFIG}: no string members found in ${mod} (expected an "as const" object, an enum or a StrEnum)`,
      );
    }
    for (const [name, value] of parsed) {
      if (value !== '' && !tables[py ? 'py' : 'ts'].has(value)) {
        tables[py ? 'py' : 'ts'].set(value, name);
      }
    }
  }
  return tables;
}

const vocabLiteral = {
  // Replaces the v3 `no-vocab-literal` ast-grep rule, whose regex was filled in by hand.
  id: 'vocab-literal',
  optIn: [VOCAB_CONFIG],
  exts: VOCAB_EXT,
  stages: ['edit', 'commit', 'push'],
  scan: ({ files, h }) => {
    const { modules, ignore } = vocabConfig(h);
    const skip = new Set(modules.map((m) => h.rel(m)));
    const candidates = (files ?? h.projectFiles(VOCAB_EXT)).filter(
      (f) => !skip.has(f) && !TEST_FILE.test(f) && !ignore.some((re) => re.test(f)),
    );
    const pyModules = modules.filter((m) => PY_EXT.test(m));
    const tsApi = pyModules.length < modules.length ? loadTypescript(h) : null;
    const py = readPython(
      h,
      pyModules,
      candidates.filter((f) => PY_EXT.test(f)),
    );
    const tables = vocabTables(h, modules, tsApi, py.vocab);
    const found = [];
    for (const file of candidates) {
      const isPy = PY_EXT.test(file);
      const table = tables[isPy ? 'py' : 'ts'];
      if (table.size === 0) continue;
      const read = isPy
        ? py.scan[file].map(([value, line]) => ({ value, line }))
        : tsLiterals(tsApi, file, h.read(file));
      for (const { value, line } of read) {
        const name = table.get(value);
        if (name === undefined) continue;
        found.push({
          rule: name,
          file,
          line,
          message: `use ${name}, not the raw string ${JSON.stringify(value)}. New values go in the vocab module.`,
        });
      }
    }
    return found;
  },
};

// ── core: every repo ──

// ls-lint reports { path: { ".ext": ["rule" | "exists:0 (found N)"] } }.
const lsLintEntry = (file, ext, text) => {
  const rule = text.replace(/ \(found \d+\)$/, '');
  const times = Number(/\(found (\d+)\)$/.exec(text)?.[1] ?? 1);
  const entry = {
    rule: `${ext.replace(/^\./, '')}-${rule}`,
    file,
    message: `${ext} name breaks ${rule}`,
  };
  return Array.from({ length: times }, () => entry);
};

const lsLintFindings = ([file, byExt]) =>
  Object.entries(byExt).flatMap(([ext, texts]) =>
    texts.flatMap((text) => lsLintEntry(file, ext, text)),
  );

const core = {
  id: 'core',
  detect: [],
  tools: [
    {
      // Custom structural rules (vocabulary literals, banned identifiers). `sg` is a deprecated alias.
      id: 'ast-grep',
      optIn: ['sgconfig.yml'],
      exts: /\.(?:[cm]?[jt]sx?|py|rs|java|go|kt|swift|c|cc|cpp|h|hpp|cs|rb|php|dart)$/,
      stages: ['edit', 'commit', 'push'],
      run: ({ files, h }) => ({
        cmd: h.bin('ast-grep') ?? h.needBin('sg'),
        args: ['scan', '--json=stream', ...(files ?? [])],
      }),
      parse: (out) =>
        out.stdout
          .split('\n')
          .filter((l) => l.startsWith('{'))
          .map((l) => {
            const d = json('ast-grep', l);
            return {
              rule: d.ruleId,
              file: d.file,
              line: d.range.start.line + 1,
              message: d.message,
            };
          }),
    },
    vocabLiteral,
    {
      // Folder and extension naming. Tree rules, so it always runs whole. A banned extension
      // (`exists:0`) is reported on its directory with a count ("found 2"); it is expanded to one
      // finding per file so the key stays stable while the count moves.
      id: 'ls-lint',
      optIn: ['.ls-lint.yml'],
      stages: ['edit', 'commit', 'push'],
      whole: true,
      run: ({ h }) => ({ cmd: h.needBin('ls-lint'), args: ['-error-output-format', 'json'] }),
      parse: (out) =>
        out.status === 0 ? [] : Object.entries(json('ls-lint', out.stderr)).flatMap(lsLintFindings),
    },
    {
      // Spelling and banned synonyms (`flagWords`), in code and docs.
      id: 'cspell',
      optIn: ['cspell.json', '.cspell.json'],
      track: MD_EXT,
      stages: ['edit', 'commit', 'push'],
      run: ({ files, h }) => ({
        cmd: h.needBin('cspell'),
        args: [
          'lint',
          '--no-progress',
          '--no-summary',
          '--no-color',
          '--gitignore',
          '--no-must-find-files',
          ...(files ?? ['**']),
        ],
      }),
      parse: lines(
        /^(.+?):(\d+):\d+ - (Forbidden|Unknown) word \(([^)]+)\)/,
        ([, file, row, kind, word]) => ({
          rule: `${kind.toLowerCase()}-word`,
          file,
          line: +row,
          message: `${kind.toLowerCase()} word "${word}"`,
        }),
      ),
    },
    {
      id: 'markdownlint',
      optIn: ['.markdownlint-cli2.jsonc', '.markdownlint-cli2.yaml'],
      exts: MD_EXT,
      stages: ['commit', 'push'],
      run: ({ files, h }) => {
        const docs = targets({ files }, h.projectFiles(MD_EXT));
        return docs.length === 0
          ? null
          : { cmd: h.needBin('markdownlint-cli2'), args: ['--no-globs', ...docs] };
      },
      parse: lines(
        /^(.+?):(\d+)(?::\d+)? (?:error|warning) (MD\d+)\/\S+ (.*)$/,
        ([, file, row, rule, message]) => ({ rule, file, line: +row, message }),
        'stderr',
      ),
      // markdownlint exits 1 on findings and 2 on a crash; a crash prints no findings.
      ok: [0, 1],
    },
    {
      // Offline in hooks (local links and anchors). GUARDRAILS_ONLINE=1 (CI) checks URLs too.
      // Timeouts are not findings: a slow host must not fail the gate.
      id: 'lychee',
      optIn: ['lychee.toml', '.lychee.toml'],
      exts: MD_EXT,
      stages: ['commit', 'push'],
      ok: [0, 2],
      quiet: [2],
      run: ({ files, online, h }) => {
        const docs = targets({ files }, h.projectFiles(MD_EXT));
        if (docs.length === 0) return null;
        const config = h.exists('lychee.toml') ? 'lychee.toml' : '.lychee.toml';
        const mode = online ? [] : ['--offline'];
        return {
          cmd: 'lychee',
          args: ['--config', config, '--no-progress', '--format', 'json', ...mode, ...docs],
        };
      },
      // Exit 2 is lychee's "links failed". Exit 1 is a runtime or config error and throws. A report
      // without error_map, or exit 2 with no failed link and no timeout, means the format changed.
      parse: (out, { h }) => {
        const report = json('lychee', out.stdout);
        if (typeof report.error_map !== 'object' || report.error_map === null) {
          throw new Error('lychee report has no error_map; its output format changed');
        }
        const found = Object.entries(report.error_map).flatMap(([file, errors]) =>
          errors.map((e) => ({
            rule: 'broken-link',
            file,
            line: e.span?.line,
            message: `${e.url.replace(`file://${h.ROOT}/`, '')}: ${e.status?.text ?? 'unreachable'}`,
          })),
        );
        const timeouts = Object.keys(report.timeout_map ?? {}).length;
        if (out.status === 2 && found.length === 0 && timeouts === 0) {
          throw new Error('lychee exited 2 but its report lists no failed link');
        }
        return found;
      },
    },
    {
      // Duplication is a relation between files, so it ratchets as one percentage that may only
      // go down. Full checks only.
      id: 'jscpd',
      optIn: ['.jscpd.json'],
      stages: ['push'],
      metric: {
        name: 'duplication',
        direction: 'down',
        unit: '%',
        advice: 'Remove the new copies.',
      },
      measure: ({ tmp, h }) => {
        const r = h.run(h.needBin('jscpd'), [
          '--reporters',
          'json',
          '--output',
          tmp(''),
          '--silent',
        ]);
        if (!h.exists(tmp('jscpd-report.json'))) {
          throw new Error(`jscpd failed (exit ${r.status}):\n${tail(r.stderr || r.stdout)}`);
        }
        const report = json('jscpd', h.read(tmp('jscpd-report.json')));
        const detail = (report.duplicates ?? [])
          .toSorted((a, b) => b.lines - a.lines)
          .slice(0, 5)
          .map(
            (c) =>
              `${c.firstFile.name}:${c.firstFile.start} = ${c.secondFile.name}:${c.secondFile.start} (${c.lines} lines)`,
          );
        // 0% duplication from a scan of nothing (a wrong path) must not read as perfect.
        if (!(report.statistics?.total?.sources > 0)) {
          throw new Error('jscpd scanned no files; check "path" and "format" in .jscpd.json');
        }
        return { value: report.statistics.total.percentage, detail };
      },
    },
    {
      // File-level hygiene from .editorconfig (final newline, indent style, trailing space).
      id: 'editorconfig-checker',
      optIn: ['.ecrc'],
      stages: ['commit', 'push'],
      run: ({ files, h }) => ({
        cmd: h.needBin('editorconfig-checker'),
        args: ['-format', 'gcc', '-no-color', ...(files ?? [])],
      }),
      parse: lines(/^(.+?):(\d+):\d+: error: (.*)$/, ([, file, row, message]) => ({
        rule: message.replace(/\d+/g, 'N').replaceAll(/\W+/g, '-').replace(/-$/, ''),
        file,
        line: +row,
        message,
      })),
    },
    {
      // Lints .github/workflows. Needs the actionlint binary on PATH.
      id: 'actionlint',
      optIn: ['.github/actionlint.yaml', '.github/actionlint.yml'],
      exts: /^\.github\/workflows\/.*\.ya?ml$/,
      stages: ['commit', 'push'],
      run: ({ files }) => ({
        cmd: 'actionlint',
        args: ['-format', '{{json .}}', ...(files ?? [])],
      }),
      parse: (out) =>
        json('actionlint', out.stdout || '[]').map((e) => ({
          rule: e.kind ?? e.Kind,
          file: e.filepath ?? e.Filepath,
          line: e.line ?? e.Line,
          message: e.message ?? e.Message,
        })),
    },
  ],
};

// ── python: every tool runs through `uv run` ──

const uvRun = (...args) => ({ cmd: 'uv', args: ['run', ...args] });
const inPyproject = (section) => ({
  file: 'pyproject.toml',
  has: new RegExp(`^\\[tool\\.${section}`, 'm'),
});

const python = {
  id: 'python',
  detect: [/(^|\/)pyproject\.toml$/, /(^|\/)uv\.lock$/],
  tools: [
    {
      id: 'ruff',
      optIn: [inPyproject('ruff'), 'ruff.toml', '.ruff.toml'],
      exts: PY_EXT,
      stages: ['edit', 'commit', 'push'],
      run: ({ files }) =>
        uvRun('ruff', 'check', '--output-format', 'json', '--no-cache', ...(files ?? ['.'])),
      parse: (out) =>
        json('ruff', out.stdout).map((d) => ({
          rule: d.code ?? 'syntax-error',
          file: d.filename,
          line: d.location?.row,
          message: d.message,
        })),
    },
    {
      id: 'ruff-format',
      optIn: [inPyproject('ruff'), 'ruff.toml', '.ruff.toml'],
      exts: PY_EXT,
      stages: ['commit', 'push'],
      run: ({ files }) => uvRun('ruff', 'format', '--check', '--no-cache', ...(files ?? ['.'])),
      // ruff 0.16 prints `unformatted: File would be reformatted` then ` --> path:line:col`;
      // older versions print `Would reformat: path`.
      parse: lines(/^(?:Would reformat: (.+)|\s+--> (.+?):\d+:\d+)$/, (m) => ({
        rule: 'format',
        file: m[1] ?? m[2],
        message: 'run ruff format',
      })),
    },
    {
      // Whole project: a type error in one file can come from a change in another.
      id: 'pyright',
      optIn: [inPyproject('pyright'), 'pyrightconfig.json'],
      exts: PY_EXT,
      stages: ['commit', 'push'],
      whole: true,
      run: () => uvRun('pyright', '--outputjson'),
      parse: (out) =>
        (json('pyright', out.stdout).generalDiagnostics ?? [])
          .filter((d) => d.severity === 'error' || d.severity === 'warning')
          .map((d) => ({
            rule: d.rule ?? 'pyright',
            file: d.file,
            line: (d.range?.start?.line ?? 0) + 1,
            message: d.message,
          })),
    },
    {
      id: 'tach',
      optIn: ['tach.toml'],
      exts: PY_EXT,
      stages: ['push'],
      whole: true,
      run: () => uvRun('tach', 'check', '--output', 'json'),
      parse: (out) =>
        json('tach', out.stdout).map((d) => {
          const { file_path: file, line_number: line, details } = d.Located ?? d;
          const rule = Object.keys(details?.Code ?? {})[0] ?? 'configuration';
          const { usage_module: from, definition_module: to } = details?.Code?.[rule] ?? {};
          return {
            rule,
            file: file ?? 'tach.toml',
            line,
            message: from && to ? `${from} may not depend on ${to}` : rule,
          };
        }),
    },
    {
      id: 'deptry',
      optIn: [inPyproject('deptry')],
      exts: PY_EXT,
      stages: ['push'],
      whole: true,
      run: ({ tmp, h }) =>
        uvRun(
          'deptry',
          h.exists('src') ? 'src' : '.',
          '--no-ansi',
          '--json-output',
          tmp('deptry.json'),
        ),
      parse: (out, { tmp, h }) => {
        if (!h.exists(tmp('deptry.json')))
          throw new Error(`deptry failed (exit ${out.status}):\n${tail(out.stderr)}`);
        return json('deptry', h.read(tmp('deptry.json'))).map((d) => ({
          rule: d.error.code,
          file: d.location.file,
          line: d.location.line ?? 0,
          message: d.error.message,
        }));
      },
    },
    {
      id: 'vulture',
      optIn: [inPyproject('vulture')],
      exts: PY_EXT,
      stages: ['push'],
      whole: true,
      ok: [0, 3],
      // Exit 3 means dead code was found. The ruff filter below may legitimately empty the list, so
      // the unreadable-output check is done here, on the unfiltered lines.
      quiet: [3],
      run: () => uvRun('vulture'),
      parse: (out, { h }) => {
        const all = lines(/^(.+?):(\d+): (.+?) \(\d+% confidence\)/, ([, file, row, text]) => ({
          rule: text
            .replace(/'[^']*'/g, '')
            .trim()
            .replaceAll(/\W+/g, '-'),
          file,
          line: +row,
          message: text,
        }))(out);
        if (out.status === 3 && all.length === 0) {
          throw new Error(
            `vulture found dead code but printed nothing readable:\n${tail(out.stdout)}`,
          );
        }
        // ruff F401 owns unused imports, so vulture does not report them a second time.
        return all.filter((f) => !(f.rule === 'unused-import' && h.active('ruff')));
      },
    },
    {
      // Test coverage may only go up. Needs pytest-cov in the dev group.
      id: 'pytest-cov',
      optIn: [inPyproject('coverage')],
      stages: ['ci'],
      metric: {
        name: 'python-coverage',
        direction: 'up',
        unit: '%',
        advice: 'Add tests for the new code.',
      },
      measure: ({ tmp, h }) => {
        const r = h.run('uv', [
          'run',
          'pytest',
          '--cov',
          `--cov-report=json:${tmp('cov.json')}`,
          '-q',
        ]);
        // Failing tests still write a coverage report. They must fail the gate, not pass with a number.
        if (r.status !== 0 || !h.exists(tmp('cov.json'))) {
          throw new Error(`pytest failed (exit ${r.status}):\n${tail(r.stdout || r.stderr)}`);
        }
        const totals = json('pytest-cov', h.read(tmp('cov.json'))).totals;
        // coverage.py reports 100% for a run that measured no statements; that is not coverage.
        if (!(totals?.num_statements > 0)) {
          throw new Error('pytest-cov measured no statements; check [tool.coverage.run] source');
        }
        return { value: totals.percent_covered };
      },
    },
  ],
};

// ── mule: MuleSoft applications (Maven, Mule XML, DataWeave, MUnit) ──

const MULE_FILES =
  /(^|\/)src\/(?:main|test)\/(?:mule|munit|resources)\/.*\.(?:xml|dwl|raml|ya?ml|properties)$/;
const MULE_PROJECT = /(^|\/)mule-artifact\.json$/;
const MULE_CONFIG = '.mulelintrc.json';
const join2 = (dir, file) => (dir === '.' ? file : `${dir}/${file}`);
const dirOf = (file) => file.split('/').slice(0, -1).join('/') || '.';

// Mule applications in the repo: the directories that hold a mule-artifact.json.
const muleProjects = (h) => h.projectFiles(MULE_PROJECT).map(dirOf);

const mule = {
  id: 'mule',
  detect: [MULE_PROJECT, /(^|\/)src\/main\/mule\/.+\.xml$/],
  tools: [
    {
      // mule-lint (@sfdxy/mule-lint), config in .mulelintrc.json (profile via `extends`).
      // Info findings are advisory and are not counted.
      id: 'mule-lint',
      optIn: [MULE_CONFIG],
      exts: MULE_FILES,
      stages: ['edit', 'commit', 'push'],
      whole: true,
      scan: ({ h }) =>
        muleProjects(h).flatMap((dir) => {
          const r = h.run(h.needBin('mule-lint'), [
            h.safe(dir),
            '--config',
            MULE_CONFIG,
            '--format',
            'json',
          ]);
          if (r.status !== 0 && r.status !== 1) {
            throw new Error(`mule-lint failed (exit ${r.status}):\n${tail(r.stderr || r.stdout)}`);
          }
          const found = json('mule-lint', r.stdout)
            .filter((d) => d.severity === 'error' || d.severity === 'warning')
            .map((d) => ({
              rule: d.ruleId,
              file: d.filePath ?? join2(dir, d.relativePath),
              line: d.line,
              message: d.message,
            }));
          return h.settle('mule-lint', r, found);
        }),
    },
    {
      // Mule XML formatting. There is no maintained CLI formatter for DataWeave (.dwl) files, so
      // those are not format-checked; mule-lint's DW rules cover their content.
      id: 'mule-format',
      optIn: [MULE_CONFIG],
      exts: MULE_FILES,
      stages: ['commit', 'push'],
      whole: true,
      scan: ({ h }) =>
        muleProjects(h).flatMap((dir) => {
          const r = h.run(h.needBin('mule-lint'), ['format', '--check', h.safe(dir)]);
          if (r.status !== 0 && r.status !== 1) {
            throw new Error(
              `mule-lint format failed (exit ${r.status}):\n${tail(r.stderr || r.stdout)}`,
            );
          }
          const found = lines(/^\s*✗ (.+?) \(needs formatting\)/, ([, file]) => ({
            rule: 'format',
            file: join2(dir, file),
            message: 'run mule-lint format',
          }))(r);
          return h.settle('mule-format', r, found);
        }),
    },
    {
      // Plain-text secrets in properties and YAML. Values must be a ${placeholder} or an
      // encrypted ![...] Secure Properties value.
      id: 'mule-secrets',
      optIn: [MULE_CONFIG],
      exts: /(^|\/)src\/(?:main|test)\/resources\/.*\.(?:properties|ya?ml)$/,
      stages: ['edit', 'commit', 'push'],
      scan: ({ files, h }) => {
        const key = /(?:pass(?:word|wd)?|secret|token|api[-_.]?key|private[-_.]?key|credential)/i;
        const found = [];
        const all =
          files ?? h.projectFiles(/(^|\/)src\/(?:main|test)\/resources\/.*\.(?:properties|ya?ml)$/);
        for (const file of all) {
          h.read(file)
            .split('\n')
            .forEach((text, i) => {
              const m = /^\s*([\w.-]+)\s*[=:]\s*(.+?)\s*$/.exec(text);
              if (!m || !key.test(m[1])) return;
              const value = m[2].replace(/^["']|["']$/g, '');
              if (value === '' || value.startsWith('${') || value.startsWith('![')) return;
              found.push({
                rule: 'plain-secret',
                file,
                line: i + 1,
                message: `"${m[1]}" holds a plain value; use \${placeholder} or an encrypted ![...] value`,
              });
            });
        }
        return found;
      },
    },
    {
      // MUnit through Maven. The coverage floor is requiredApplicationCoverage in pom.xml, so a
      // coverage miss fails `mvn test`. Only poms that configure the MUnit plugin run.
      id: 'munit',
      optIn: [{ file: 'pom.xml', has: /munit-maven-plugin/ }],
      // Runs the whole suite: CI only (GUARDRAILS_CI=1), once, never on pre-push.
      stages: ['ci'],
      whole: true,
      scan: ({ h }) =>
        h
          .projectFiles(/(^|\/)pom\.xml$/)
          .filter((pom) => /munit-maven-plugin/.test(h.read(pom)))
          .flatMap((pom) => {
            const r = h.run('mvn', ['-B', '-ntp', '-q', '-f', h.safe(pom), 'test']);
            return r.status === 0
              ? []
              : [
                  {
                    rule: 'tests-or-coverage-failed',
                    file: pom,
                    message: tail(r.stdout || r.stderr),
                    always: true,
                  },
                ];
          }),
    },
  ],
};

// ── salesforce: Apex, LWC, metadata (always `sf`, never `sfdx`) ──

const APEX_EXT = /\.(?:cls|trigger|apex)$/;
const SF_CODE = /\.(?:cls|trigger|apex|js|html|cmp|page|component)$/;
const SF_MARKER = ['code-analyzer.yml', 'code-analyzer.yaml'];

// The package directories of sfdx-project.json (force-app by default), or the repo root.
const packageDirs = (h) => {
  if (!h.exists('sfdx-project.json')) return ['.'];
  const paths = (
    json('sfdx-project.json', h.read('sfdx-project.json')).packageDirectories ?? []
  ).map((p) => p.path);
  return paths.length > 0 ? paths : ['.'];
};

const salesforce = {
  id: 'salesforce',
  detect: [/(^|\/)sfdx-project\.json$/, /\.(?:cls|trigger)$/],
  tools: [
    {
      // Salesforce Code Analyzer: PMD for Apex, ESLint for LWC, retire-js, regex rules. About ten
      // seconds a run, so it is a pre-commit and CI check, not an edit hook.
      id: 'code-analyzer',
      optIn: SF_MARKER,
      exts: SF_CODE,
      stages: ['commit', 'push'],
      // The workspace is the package directories of sfdx-project.json, so tooling files such as
      // scripts/ are not analysed as LWC.
      run: ({ files, tmp, h }) => {
        const dirs = packageDirs(h);
        const inside = (files ?? []).filter((f) => dirs.some((d) => f.startsWith(`${d}/`)));
        if (files && inside.length === 0) return null;
        return {
          cmd: 'sf',
          args: [
            'code-analyzer',
            'run',
            ...dirs.flatMap((d) => ['--workspace', h.safe(d)]),
            ...inside.flatMap((f) => ['--target', f]),
            '--output-file',
            tmp('code-analyzer.json'),
          ],
        };
      },
      parse: (out, { tmp, h }) => {
        if (!h.exists(tmp('code-analyzer.json'))) {
          throw new Error(
            `sf code-analyzer wrote no results (exit ${out.status}):\n${tail(out.stderr)}`,
          );
        }
        return json('code-analyzer', h.read(tmp('code-analyzer.json'))).violations.map((v) => {
          const at = v.locations[v.primaryLocationIndex ?? 0];
          return {
            rule: `${v.engine}.${v.rule}`,
            file: at.file,
            line: at.startLine,
            message: v.message,
          };
        });
      },
    },
    {
      // Apex formatting through prettier-plugin-apex. LWC JS, HTML and CSS are covered by the
      // base Prettier check (`format:check`).
      id: 'prettier-apex',
      optIn: [
        { file: '.prettierrc', has: /prettier-plugin-apex/ },
        { file: '.prettierrc.json', has: /prettier-plugin-apex/ },
      ],
      exts: APEX_EXT,
      stages: ['commit', 'push'],
      run: ({ files, h }) => {
        const apex = files ?? h.projectFiles(APEX_EXT);
        return apex.length === 0
          ? null
          : { cmd: h.needBin('prettier'), args: ['--list-different', '--ignore-unknown', ...apex] };
      },
      parse: lines(/^([^[\s].*)$/, ([, file]) => ({
        rule: 'format',
        file,
        message: 'run prettier --write',
      })),
    },
    {
      // Metadata sanity: every class and trigger has its -meta.xml, and no apiVersion is older
      // than sourceApiVersion in sfdx-project.json.
      id: 'sf-metadata',
      optIn: SF_MARKER,
      exts: /\.(?:cls|trigger)$/,
      stages: ['commit', 'push'],
      scan: ({ files, h }) => {
        const project = h.exists('sfdx-project.json')
          ? json('sfdx-project.json', h.read('sfdx-project.json'))
          : {};
        const want = Number.parseFloat(project.sourceApiVersion);
        const code = files ?? h.projectFiles(/\.(?:cls|trigger)$/);
        return code.flatMap((file) => {
          const meta = `${file}-meta.xml`;
          if (!h.exists(meta))
            return [{ rule: 'missing-meta-xml', file, message: `${file} has no ${meta}` }];
          const version = /<apiVersion>([\d.]+)<\/apiVersion>/.exec(h.read(meta))?.[1];
          if (!want || !version || Number.parseFloat(version) >= want) return [];
          const message = `apiVersion ${version} is older than sourceApiVersion ${project.sourceApiVersion}`;
          return [{ rule: 'stale-api-version', file: meta, message }];
        });
      },
    },
    {
      // Apex coverage floor from an org test run (`sf apex run test`). Needs an authenticated
      // test org named in guardrails/apex-coverage.json; never point it at production.
      id: 'apex-coverage',
      optIn: ['guardrails/apex-coverage.json'],
      // An org test run can take up to an hour: CI only (GUARDRAILS_CI=1), once, never on pre-push.
      stages: ['ci'],
      metric: {
        name: 'apex-coverage',
        direction: 'up',
        unit: '%',
        advice: 'Add Apex tests for the new code.',
      },
      measure: ({ h }) => {
        const cfg = json('apex-coverage.json', h.read('guardrails/apex-coverage.json'));
        const r = h.run('sf', [
          'apex',
          'run',
          'test',
          '--target-org',
          cfg.targetOrg,
          '--test-level',
          cfg.testLevel ?? 'RunLocalTests',
          '--code-coverage',
          '--wait',
          String(cfg.waitMinutes ?? 60),
          '--json',
        ]);
        const summary = json('sf apex run test', r.stdout).result?.summary;
        if (!summary)
          throw new Error(
            `sf apex run test returned no summary (exit ${r.status}):\n${tail(r.stdout)}`,
          );
        if (summary.outcome !== 'Passed')
          throw new Error(`Apex tests ${summary.outcome}: ${summary.failing} failing`);
        // An org with no tests run has no coverage to report; do not read that as a number.
        if (!(Number(summary.testsRan) > 0)) {
          throw new Error('sf apex run test ran no tests; there is no coverage to record');
        }
        return { value: Number.parseFloat(summary.orgWideCoverage) };
      },
    },
  ],
};

// ── shell ──

const SH_EXT = /\.(?:sh|bash)$/;
const SH_MARKER = ['.shellcheckrc'];

const shell = {
  id: 'shell',
  detect: [SH_EXT, /(^|\/)\.shellcheckrc$/],
  tools: [
    {
      id: 'shellcheck',
      optIn: SH_MARKER,
      exts: SH_EXT,
      stages: ['edit', 'commit', 'push'],
      run: ({ files, h }) => {
        const scripts = files ?? h.projectFiles(SH_EXT);
        return scripts.length === 0
          ? null
          : { cmd: 'shellcheck', args: ['-f', 'json1', ...scripts] };
      },
      parse: (out) =>
        (json('shellcheck', out.stdout).comments ?? []).map((c) => ({
          rule: `SC${c.code}`,
          file: c.file,
          line: c.line,
          message: c.message,
        })),
    },
    {
      // Formatting from .editorconfig (shfmt reads indent settings there).
      id: 'shfmt',
      optIn: SH_MARKER,
      exts: SH_EXT,
      stages: ['commit', 'push'],
      run: ({ files, h }) => {
        const scripts = files ?? h.projectFiles(SH_EXT);
        return scripts.length === 0 ? null : { cmd: 'shfmt', args: ['-l', ...scripts] };
      },
      parse: lines(/^(.+\.(?:sh|bash))$/, ([, file]) => ({
        rule: 'format',
        file,
        message: 'run shfmt -w',
      })),
    },
  ],
};

// ── docker ──

const DOCKERFILE = /(^|\/)(?:Dockerfile[^/]*|[^/]*\.Dockerfile)$/;
const COMPOSE = /(^|\/)(?:docker-)?compose[^/]*\.ya?ml$/;
