// ── rust (Cargo) ──

const RS_EXT = /\.rs$/;
// rustc's closing summaries, which clippy -D warnings emits after any error.
const RUSTC_SUMMARY = /^(aborting due to|could not compile|\d+ (warnings?|errors?) emitted)/;

const rust = {
  id: 'rust',
  detect: [/(^|\/)Cargo\.toml$/],
  tools: [
    {
      id: 'cargo-fmt',
      optIn: ['rustfmt.toml', '.rustfmt.toml'],
      exts: RS_EXT,
      stages: ['commit', 'push'],
      whole: true,
      run: () => ({ cmd: 'cargo', args: ['fmt', '--check'] }),
      parse: lines(/^Diff in (.+?):\d+/, ([, file]) => ({
        rule: 'format',
        file,
        message: 'run cargo fmt',
      })),
    },
    {
      // -D warnings turns every warning into an error. 101 is cargo's "compilation failed" exit.
      id: 'clippy',
      optIn: ['clippy.toml', '.clippy.toml'],
      exts: RS_EXT,
      stages: ['commit', 'push'],
      whole: true,
      ok: [0, 101],
      run: () => ({
        cmd: 'cargo',
        args: ['clippy', '--all-targets', '--message-format', 'json', '--', '-D', 'warnings'],
      }),
      // --all-targets compiles a file once per target, so the same lint can print twice.
      // A compile error (rustc E-codes, or an error with no code) means the build is broken, not
      // that there is lint debt: it is an always-finding, never baselined, and always fails.
      parse: (out) => {
        const seen = new Map();
        for (const l of out.stdout.split('\n')) {
          if (!l.startsWith('{')) continue;
          const d = json('clippy', l);
          const m = d.message;
          if (d.reason !== 'compiler-message' || !m) continue;
          const span = m.spans?.find((s) => s.is_primary);
          // rustc closes with summary messages (level error, no code, no span). They say how many
          // errors there were, not what they were, so they are never findings themselves.
          if (RUSTC_SUMMARY.test(m.message)) continue;
          // A compile error needs a primary span: an E-code error, or a code-less one (a syntax
          // error). A code-less error with no span is a summary, not a failure we can place.
          const compileError =
            m.level === 'error' && Boolean(span) && (!m.code || /^E\d{4}$/.test(m.code.code));
          if (!compileError && (!m.code || !span)) continue;
          const found = {
            rule: compileError ? (m.code?.code ?? 'compile-error') : m.code.code,
            file: span?.file_name ?? 'Cargo.toml',
            line: span?.line_start,
            message: m.message,
            always: compileError,
          };
          seen.set(`${found.rule}|${found.file}|${found.line}|${found.message}`, found);
        }
        return [...seen.values()];
      },
    },
    {
      id: 'cargo-deny',
      optIn: ['deny.toml'],
      stages: ['push'],
      whole: true,
      run: () => ({ cmd: 'cargo', args: ['deny', 'check'] }),
      parse: (out) =>
        out.status === 0
          ? []
          : [
              {
                rule: 'policy',
                file: 'deny.toml',
                message: tail(out.stderr || out.stdout),
                always: true,
              },
            ],
    },
    {
      // Unused dependencies. Switched on by [package.metadata.cargo-machete] in Cargo.toml.
      id: 'cargo-machete',
      optIn: [{ file: 'Cargo.toml', has: /cargo-machete/ }],
      stages: ['push'],
      whole: true,
      run: () => ({ cmd: 'cargo', args: ['machete'] }),
      parse: (out) => {
        let manifest = 'Cargo.toml';
        return out.stdout.split('\n').flatMap((l) => {
          const header = /^\S+ -- (.+):$/.exec(l);
          if (header) manifest = header[1].replace(/^\.\//, '');
          const dep = /^\t(\S+)$/.exec(l);
          return dep
            ? [
                {
                  rule: 'unused-dependency',
                  file: manifest,
                  message: `unused dependency ${dep[1]}`,
                },
              ]
            : [];
        });
      },
    },
  ],
};

// ── dart and flutter ──

const DART_EXT = /\.dart$/;
const DART_MARKER = ['analysis_options.yaml'];
const isFlutter = (h) => h.exists('pubspec.yaml') && /sdk:\s*flutter/.test(h.read('pubspec.yaml'));

const dart = {
  id: 'dart',
  detect: [/(^|\/)pubspec\.yaml$/, DART_EXT],
  tools: [
    {
      id: 'dart-format',
      optIn: DART_MARKER,
      exts: DART_EXT,
      stages: ['commit', 'push'],
      run: ({ files }) => ({
        cmd: 'dart',
        args: ['format', '--output=none', '--set-exit-if-changed', ...(files ?? ['.'])],
      }),
      parse: lines(/^Changed (.+)$/, ([, file]) => ({
        rule: 'format',
        file,
        message: 'run dart format',
      })),
    },
    {
      // dart analyze --format=machine prints SEVERITY|TYPE|CODE|FILE|LINE|COLUMN|LENGTH|MESSAGE.
      // Flutter projects use `flutter analyze`, which has no machine format.
      id: 'dart-analyze',
      optIn: DART_MARKER,
      exts: DART_EXT,
      stages: ['commit', 'push'],
      whole: true,
      ok: [0, 1, 2, 3],
      run: ({ h }) =>
        isFlutter(h)
          ? { cmd: 'flutter', args: ['analyze', '--no-pub'] }
          : { cmd: 'dart', args: ['analyze', '--format=machine'] },
      parse: (out, { h }) =>
        isFlutter(h)
          ? lines(
              /^\s*(?:error|warning|info) • (.+?) • (.+?):(\d+):\d+ • (\S+)/,
              ([, message, file, row, rule]) => ({
                rule,
                file,
                line: +row,
                message,
              }),
            )(out)
          : lines(
              /^(?:ERROR|WARNING|INFO)\|[^|]*\|([^|]*)\|([^|]*)\|(\d+)\|\d+\|\d+\|(.*)$/,
              ([, rule, file, row, message]) => ({
                rule: rule.toLowerCase(),
                file,
                line: +row,
                message,
              }),
            )({ stdout: `${out.stdout}\n${out.stderr}` }),
    },
    {
      // Coverage may only go up. Flutter packages only (`flutter test --coverage`).
      id: 'flutter-coverage',
      optIn: DART_MARKER,
      stages: ['ci'],
      metric: {
        name: 'flutter-coverage',
        direction: 'up',
        unit: '%',
        advice: 'Add tests for the new code.',
      },
      measure: ({ h }) => {
        if (!isFlutter(h)) return null;
        // Remove any old report first, so the one read below was written by this run.
        h.remove('coverage/lcov.info');
        const r = h.run('flutter', ['test', '--coverage']);
        if (r.status !== 0)
          throw new Error(`flutter test failed (exit ${r.status}):\n${tail(r.stdout || r.stderr)}`);
        const lcov = h.exists('coverage/lcov.info') ? h.read('coverage/lcov.info') : '';
        const sum = (tag) =>
          lcov
            .split('\n')
            .filter((l) => l.startsWith(`${tag}:`))
            .reduce((n, l) => n + Number(l.slice(tag.length + 1)), 0);
        const found = sum('LF');
        // An empty, truncated or all-zero report is not 100% coverage.
        // Every record is closed (a report cut off after the first one still contains one
        // end_of_record) and the file ends on one.
        const opened = lcov.split('\n').filter((l) => l.startsWith('SF:')).length;
        const closed = lcov.split('\n').filter((l) => l.trim() === 'end_of_record').length;
        if (!lcov.trimEnd().endsWith('end_of_record') || opened !== closed || !(found > 0)) {
          throw new Error(
            'flutter test wrote no usable coverage/lcov.info (empty, truncated or no lines)',
          );
        }
        return { value: (sum('LH') / found) * 100 };
      },
    },
  ],
};

// ── cpp and PlatformIO firmware ──

const CPP_EXT = /\.(?:c|cc|cpp|cxx|h|hh|hpp|ino)$/;

const cpp = {
  id: 'cpp',
  detect: [/(^|\/)platformio\.ini$/, /(^|\/)\.clang-format$/, CPP_EXT],
  tools: [
    {
      id: 'clang-format',
      optIn: ['.clang-format'],
      exts: CPP_EXT,
      stages: ['commit', 'push'],
      run: ({ files, h }) => {
        const sources = files ?? h.projectFiles(CPP_EXT);
        return sources.length === 0
          ? null
          : { cmd: 'clang-format', args: ['--dry-run', '--Werror', ...sources] };
      },
      parse: lines(
        /^(.+?):(\d+):\d+: (?:error|warning): code should be clang-formatted/,
        ([, file, row]) => ({ rule: 'format', file, line: +row, message: 'run clang-format -i' }),
        'stderr',
      ),
    },
    {
      // Static analysis through `pio check` (cppcheck or clang-tidy, chosen by check_tool in
      // platformio.ini). It downloads toolchains, so it is pre-push and CI only.
      id: 'pio-check',
      optIn: [{ file: 'platformio.ini', has: /^check_tool\s*=/m }],
      stages: ['ci'],
      whole: true,
      run: () => ({ cmd: 'pio', args: ['check', '--skip-packages', '--json-output'] }),
      parse: (out) =>
        json('pio check', out.stdout).flatMap((env) =>
          (env.defects ?? []).map((d) => ({
            rule: `${env.tool ?? 'pio'}.${d.id ?? d.category ?? d.severity}`,
            file: d.file,
            line: d.line,
            message: d.message,
          })),
        ),
    },
  ],
};

// ── security: dependency advisories, own Semgrep rules, GitHub Actions audit ──

// Lockfiles osv-scanner reads. It is given each one explicitly, so a lockfile it cannot parse fails.
const LOCKFILE =
  /(?:^|\/)(?:package-lock\.json|npm-shrinkwrap\.json|pnpm-lock\.yaml|yarn\.lock|uv\.lock|poetry\.lock|Cargo\.lock|go\.mod|composer\.lock|Gemfile\.lock)$/;
const WORKFLOW = /^\.github\/workflows\/.*\.ya?ml$/;
const OSV_CONFIG = 'osv-scanner.toml';
const SEMGREP_RULES = '.semgrep';
const ZIZMOR_CONFIGS = ['.github/zizmor.yml', '.github/zizmor.yaml', 'zizmor.yml', 'zizmor.yaml'];

// zizmor exits 10 to 14 by the highest severity it found, 0 when clean, 1 on a failure.
const ZIZMOR_OK = [0, 10, 11, 12, 13, 14];

const security = {
  id: 'security',
  detect: [LOCKFILE, WORKFLOW, /(^|\/)\.semgrep\//],
  tools: [
    {
      // Known vulnerabilities in the lockfiles. Needs network access to the OSV database.
      id: 'osv-scanner',
      optIn: [OSV_CONFIG],
      exts: LOCKFILE,
      stages: ['push'],
      run: ({ files, h }) => {
        const locks = files ?? h.projectFiles(LOCKFILE);
        return locks.length === 0
          ? null
          : {
              cmd: 'osv-scanner',
              args: [
                'scan',
                'source',
                '--format',
                'json',
                '--config',
                OSV_CONFIG,
                ...locks.flatMap((f) => ['-L', f]),
              ],
            };
      },
      parse: (out) =>
        (json('osv-scanner', out.stdout).results ?? []).flatMap((r) =>
          (r.packages ?? []).flatMap((p) =>
            (p.vulnerabilities ?? []).map((v) => ({
              rule: v.id,
              file: r.source.path,
              message: `${p.package.name}@${p.package.version}: ${v.summary ?? v.details?.split('\n')[0] ?? v.id}`,
            })),
          ),
        ),
    },
    {
      // Only the rules in .semgrep/ run: nothing is fetched from the registry and no metrics are
      // sent. A full-repo scan, so it is pre-push and CI only.
      id: 'semgrep',
      optIn: [`${SEMGREP_RULES}/rules.yml`, `${SEMGREP_RULES}/rules.yaml`],
      exts: /\.(?:[cm]?[jt]sx?|py)$/,
      stages: ['push'],
      run: ({ files }) => ({
        cmd: 'semgrep',
        args: [
          'scan',
          '--metrics=off',
          '--disable-version-check',
          '--quiet',
          '--json',
          '--error',
          '--config',
          SEMGREP_RULES,
          ...(files ?? ['.']),
        ],
      }),
      // Exit 1 is "findings" (--error); 2 and up are failures. Rule ids carry the config folder
      // as a prefix ("semgrep.js-eval"), so the rule is the part after the last dot.
      parse: (out) =>
        (json('semgrep', out.stdout).results ?? []).map((r) => ({
          rule: r.check_id.split('.').at(-1),
          file: r.path,
          line: r.start?.line,
          message: r.extra?.message ?? r.check_id,
        })),
    },
    {
      // Workflow audit (injection, excessive permissions, unpinned actions). Offline: no GitHub token needed.
      id: 'zizmor',
      optIn: ZIZMOR_CONFIGS,
      exts: WORKFLOW,
      stages: ['commit', 'push'],
      ok: ZIZMOR_OK,
      run: ({ files, h }) => {
        const flows = files ?? h.projectFiles(WORKFLOW);
        const config = ZIZMOR_CONFIGS.find((f) => h.exists(f));
        return flows.length === 0
          ? null
          : {
              cmd: 'zizmor',
              args: [
                '--offline',
                '--format',
                'json-v1',
                '--no-progress',
                '--config',
                config,
                ...flows,
              ],
            };
      },
      parse: (out) =>
        json('zizmor', out.stdout)
          .filter((f) => !f.ignored)
          .map((f) => {
            const at = f.locations.find((l) => l.symbolic.kind === 'Primary') ?? f.locations[0];
            return {
              rule: f.ident,
              file: at.symbolic.key.Local.verbatim_path,
              line: at.concrete.location.start_point.row + 1,
              message: `${f.desc}: ${at.symbolic.annotation}`,
            };
          }),
    },
  ],
};

// ── playwright: e2e hygiene (fixed waits, focus, skips and quarantine, conditionals) ──
//
// ast-grep finds the code shapes, with rules generated here; the date logic of the quarantine tag
// is done in JS. See docs/decisions/0004-playwright-pack.md for why not eslint-plugin-playwright.

const PW_CONFIG = 'guardrails/playwright.json';
const PW_DEFAULTS = { include: ['**/e2e/**', '**/*.spec.*'], ignore: [] };
const PW_BATCH = 200;
// Rules that only feed the quarantine logic.
const PW_HELPERS = ['scope', 'tag'];

// A call chain that starts at a Playwright test object: test, test.describe.serial, test.info(),
// and fixture aliases named like one (authTest).
const PW_TEST = '(test|it|setup|teardown|[A-Za-z0-9_]*Test)';
const PW_CHAIN = `^(${PW_TEST}|describe|testInfo)(\\.[A-Za-z]+(\\(\\))?)*$`;

// The n-th named child, not counting comments: an argument or a statement.
const pwNth = (position) => ({ position, ofRule: { not: { kind: 'comment' } } });
const pwCallee = (rule) => ({ has: { field: 'function', ...rule } });
const isGlobList = (v) => Array.isArray(v) && v.every((g) => typeof g === 'string' && g !== '');

// One rule file per run: every rule once per ast-grep language, so each file is covered whichever
// of the three parses it. The grammars differ only in how a parameter is spelled.
function pwRules(language) {
  const js = language === 'JavaScript';
  const fn = { any: [{ kind: 'arrow_function' }, { kind: 'function_expression' }] };
  const anyFn = {
    any: [
      'arrow_function',
      'function_expression',
      'function_declaration',
      'generator_function',
      'generator_function_declaration',
      'method_definition',
    ].map((kind) => ({ kind })),
  };
  const text = { any: [{ kind: 'string' }, { kind: 'template_string' }] };
  const arg = (n, rule) => ({
    has: { field: 'arguments', has: { all: [{ nthChild: pwNth(n) }, rule] } },
  });
  const chain = pwCallee({ regex: PW_CHAIN });
  // `.only(...)` and friends on a test object, or on any alias called like a test: (title, fn).
  const modifier = (names) => ({
    all: [
      { kind: 'call_expression' },
      pwCallee({
        kind: 'member_expression',
        has: { field: 'property', regex: `^(${names})$` },
      }),
      {
        any: [
          pwCallee({ has: { field: 'object', regex: PW_CHAIN } }),
          { all: [arg(1, text), { has: { field: 'arguments', has: fn } }] },
        ],
      },
    ],
  });
  // `test.skip(condition, 'reason')`: the condition reads something at run time.
  const runtimeValue = {
    kind: 'identifier',
    not: { regex: '^(undefined|NaN|Infinity)$' },
  };
  const conditionalSkip = {
    all: [
      arg(1, {
        not: text,
        any: [runtimeValue, { has: { stopBy: 'end', ...runtimeValue } }],
      }),
      arg(2, text),
      { not: arg(3, { pattern: '$EXTRA' }) },
    ],
  };
  // `$R` is the resolve parameter of `new Promise(...)`; a sleep hands it to setTimeout.
  const name = { kind: 'identifier', pattern: '$R' };
  const param = js ? name : { kind: 'required_parameter', has: { field: 'pattern', ...name } };
  const sleep = {
    all: [
      { kind: 'new_expression' },
      { has: { field: 'constructor', regex: '^Promise$' } },
      arg(1, {
        all: [
          fn,
          {
            any: [
              { has: { field: 'parameter', ...name } },
              { has: { field: 'parameters', has: { all: [{ nthChild: 1 }, param] } } },
            ],
          },
          {
            has: {
              stopBy: 'end',
              all: [
                { kind: 'call_expression' },
                pwCallee({ regex: '^((window|globalThis)\\.)?setTimeout$' }),
                arg(1, {
                  any: [
                    name,
                    {
                      all: [
                        fn,
                        {
                          has: {
                            stopBy: 'end',
                            kind: 'call_expression',
                            has: { field: 'function', ...name },
                          },
                        },
                      ],
                    },
                  ],
                }),
              ],
            },
          },
        ],
      }),
    ],
  };
  const testCall = {
    all: [
      { kind: 'call_expression' },
      pwCallee({
        regex: `^(${PW_TEST}(\\.(only|skip|fixme|fail|slow))*|${PW_TEST}\\.step(\\.skip)?)$`,
      }),
      arg(1, { not: fn }),
    ],
  };
  const testBody = { all: [fn, { inside: { kind: 'arguments', inside: testCall } }] };
  // `if (!box) throw ...` narrows a type and fails the test; it does not branch it.
  const onlyThrows = {
    any: [
      { kind: 'throw_statement' },
      {
        kind: 'statement_block',
        has: { kind: 'throw_statement', nthChild: pwNth(1) },
        not: { has: { nthChild: pwNth(2) } },
      },
    ],
  };
  const taggedCall = { all: [{ kind: 'call_expression' }, chain] };
  const ofCall = { inside: { kind: 'arguments', inside: taggedCall } };
  const tagPair = {
    kind: 'pair',
    has: { field: 'key', regex: '^["\']?tag["\']?$' },
    inside: { kind: 'object', ...ofCall },
  };
  const rules = {
    'fixed-wait': {
      any: [
        {
          kind: 'call_expression',
          ...pwCallee({
            kind: 'member_expression',
            has: { field: 'property', regex: '^waitForTimeout$' },
          }),
        },
        sleep,
        {
          kind: 'import_specifier',
          has: { field: 'name', regex: '^setTimeout$' },
          inside: {
            stopBy: 'end',
            kind: 'import_statement',
            has: { field: 'source', regex: '^.(node:)?timers/promises.$' },
          },
        },
        {
          all: [
            { kind: 'call_expression' },
            pwCallee({ regex: '^(util\\.)?promisify$' }),
            arg(1, { regex: '^((window|globalThis)\\.)?setTimeout$' }),
          ],
        },
      ],
    },
    'focused-test': modifier('only'),
    skip: { all: [modifier('skip|fixme'), { not: conditionalSkip }] },
    'conditional-in-test': {
      any: [{ kind: 'if_statement' }, { kind: 'switch_statement' }],
      inside: { stopBy: anyFn, ...testBody },
      not: {
        kind: 'if_statement',
        has: { field: 'consequence', ...onlyThrows },
        not: { has: { field: 'alternative', pattern: '$ELSE' } },
      },
    },
    // Helpers for the quarantine logic, never findings: each Playwright call, and each
    // `@quarantine` string in the title or `tag` of one.
    scope: taggedCall,
    tag: {
      all: [
        text,
        { regex: '@quarantine\\b' },
        {
          any: [
            { all: [{ nthChild: pwNth(1) }, ofCall] },
            { inside: tagPair },
            { inside: { kind: 'array', inside: tagPair } },
          ],
        },
      ],
    },
  };
  return Object.entries(rules).map(([id, rule]) =>
    // A project may not repeat a rule id, so each carries its language (stripped after the run).
    JSON.stringify({ id: `${id}_${language}`, language, severity: 'error', message: id, rule }),
  );
}

const PW_MESSAGES = {
  'fixed-wait': 'wait for a condition (a web-first assertion, waitForURL, expect.poll), not a time',
  'focused-test': '.only hides every other test; remove it',
  skip: 'a skip needs a live @quarantine-YYYY-MM-DD tag, or the form test.skip(condition, "reason")',
  'conditional-in-test':
    'a test takes one path; split it, or choose by project, fixture or test.skip(condition, "reason")',
  'stale-quarantine':
    'quarantine has expired or has no valid date (@quarantine-YYYY-MM-DD): fix the test or renew it after review',
  suppression: 'ast-grep-ignore cannot silence playwright rules; fix the code',
};

function pwConfig(h) {
  let config;
  try {
    config = JSON.parse(h.read(PW_CONFIG));
  } catch (e) {
    throw new Error(`${PW_CONFIG} is not valid JSON: ${e.message}`, { cause: e });
  }
  const unknown = Object.keys(config ?? {}).filter((k) => !(k in PW_DEFAULTS));
  const { include, ignore } = { ...PW_DEFAULTS, ...config };
  const object = typeof config === 'object' && config !== null && !Array.isArray(config);
  if (
    !object ||
    unknown.length > 0 ||
    !isGlobList(include) ||
    include.length === 0 ||
    !isGlobList(ignore)
  ) {
    throw new Error(
      `${PW_CONFIG} takes only "include" (a non-empty list of globs) and "ignore" (a list of globs)`,
    );
  }
  return { include: include.map(globRegExp), ignore: ignore.map(globRegExp) };
}

// Runs ast-grep with our own config, so the project's sgconfig.yml cannot change what is read.
// It skips unreadable, non-UTF-8 and very large files and still exits 0, so every file handed to it
// must be reported as scanned.
function pwScan(ctx, files) {
  const { h, tmp } = ctx;
  mkdirSync(tmp('rules'), { recursive: true });
  const docs = ['TypeScript', 'Tsx', 'JavaScript'].flatMap(pwRules);
  writeFileSync(tmp('rules/playwright.yml'), docs.join('\n---\n'));
  writeFileSync(tmp('sgconfig.yml'), 'ruleDirs:\n  - rules\n');
  const cmd = h.bin('ast-grep') ?? h.needBin('sg');
  const matches = [];
  for (let i = 0; i < files.length; i += PW_BATCH) {
    const batch = files.slice(i, i + PW_BATCH);
    const r = h.run(cmd, [
      'scan',
      '--config',
      tmp('sgconfig.yml'),
      '--json=stream',
      '--inspect',
      'summary',
      ...batch.map(h.safe),
    ]);
    const fail = (why) => {
      throw new Error(`playwright: ast-grep ${why} (exit ${r.status}):\n${tail(r.stderr)}`);
    };
    if (r.status !== 0 && r.status !== 1) fail('failed');
    const counts = /scannedFileCount=(\d+),skippedFileCount=(\d+)/.exec(r.stderr);
    if (/^ERROR:/m.test(r.stderr) || !counts) fail('could not read every file');
    if (Number(counts[1]) !== batch.length || counts[2] !== '0') {
      fail('skipped files (not UTF-8, unreadable or too large)');
    }
    const found = r.stdout
      .split('\n')
      .filter((l) => l.trim() !== '')
      .map((l) => json('ast-grep', l))
      .map((m) => ({ ...m, ruleId: m.ruleId.split('_')[0] }))
      // ast-grep adds its own `unused-suppression` notes.
      .filter((m) => Object.hasOwn(PW_MESSAGES, m.ruleId) || PW_HELPERS.includes(m.ruleId));
    if (r.status === 1 && found.length === 0) fail('reported errors it did not print');
    matches.push(...found);
  }
  return matches;
}

// A tag is live through its date (UTC). A date that does not exist is never live.
function pwLive(date, today) {
  const time = Date.parse(`${date}T00:00:00Z`);
  return !Number.isNaN(time) && new Date(time).toISOString().startsWith(date) && date >= today;
}

const contains = (outer, inner) =>
  outer.range.byteOffset.start <= inner.range.byteOffset.start &&
  outer.range.byteOffset.end >= inner.range.byteOffset.end;
const size = (m) => m.range.byteOffset.end - m.range.byteOffset.start;

// Findings of one file. A skip is accepted when a live quarantine tag sits on its own call or on a
// test or describe around it.
function pwFindings(file, matches, today) {
  const of = (id) => matches.filter((m) => m.ruleId === id);
  const finding = (rule, line) => ({ rule, file, line, message: PW_MESSAGES[rule] });
  const quarantined = [];
  const stale = [];
  for (const tag of of('tag')) {
    const dates = [...tag.text.matchAll(/@quarantine\b(?:-(\d{4}-\d{2}-\d{2})(?![\w-]))?/g)];
    const owner = of('scope')
      .filter((s) => contains(s, tag))
      .toSorted((a, b) => size(a) - size(b))[0];
    for (const [, date] of dates) {
      if (date && pwLive(date, today)) quarantined.push(owner);
      else stale.push(finding('stale-quarantine', tag.range.start.line + 1));
    }
  }
  const rules = matches
    .filter((m) => !PW_HELPERS.includes(m.ruleId))
    .filter((m) => m.ruleId !== 'skip' || !quarantined.some((q) => contains(q, m)))
    .map((m) => finding(m.ruleId, m.range.start.line + 1));
  return [...rules, ...stale];
}

// `// ast-grep-ignore` would silence these rules too, so a bare one, or one that names no other
// tool's rule, is itself a finding.
function pwSuppressions(file, text) {
  return text.split('\n').flatMap((line, i) => {
    const m = /\/[/*]\s*ast-grep-ignore\b(?:\s*:([^*\n]*))?/.exec(line);
    if (!m) return [];
    const ids = (m[1] ?? '').split(',').map((s) => s.trim().split('_')[0]);
    const hides = ids.some((id) => id === '' || Object.hasOwn(PW_MESSAGES, id));
    return hides
      ? [{ rule: 'suppression', file, line: i + 1, message: PW_MESSAGES.suppression }]
      : [];
  });
}

const playwright = {
  id: 'playwright',
  detect: [/(^|\/)playwright\.config\.[cm]?[jt]s$/],
  tools: [
    {
      id: 'playwright',
      optIn: [PW_CONFIG],
      exts: TS_EXT,
      stages: ['edit', 'commit', 'push'],
      scan: (ctx) => {
        const { files, h } = ctx;
        const { include, ignore } = pwConfig(h);
        const e2e = (files ?? h.projectFiles(TS_EXT)).filter(
          (f) => include.some((re) => re.test(f)) && !ignore.some((re) => re.test(f)),
        );
        // A full run that matches nothing means the globs are wrong, not that the suite is clean.
        if (!files && e2e.length === 0) {
          throw new Error(`${PW_CONFIG}: no file matches "include"; fix the globs or remove it`);
        }
        // ast-grep reports an empty file as skipped.
        const sources = e2e.map((f) => [f, h.read(f)]).filter(([, text]) => text !== '');
        if (sources.length === 0) return [];
        const byFile = Map.groupBy(
          pwScan(
            ctx,
            sources.map(([f]) => f),
          ),
          (m) => h.rel(m.file),
        );
        const today = new Date().toISOString().slice(0, 10);
        return sources.flatMap(([file, text]) => [
          ...pwFindings(file, byFile.get(h.rel(file)) ?? [], today),
          ...pwSuppressions(file, text),
        ]);
      },
    },
  ],
};

export const PACKS = [
  core,
  ts,
  python,
  mule,
  salesforce,
  shell,
  docker,
  sql,
  rust,
  dart,
  cpp,
  security,
  playwright,
];
